 public PersistenceResult<Long>create(CreateUserPersist c,SessionIdentity i,RequestMetadata m){var roles=c.rolIds().stream().map(x->Map.<String,Object>of("rolId",x)).toList();Map<String,Object>b=new LinkedHashMap<>();b.put("usuario",map("empleadoId",c.empleadoId(),"nombreUsuario",c.nombreUsuario(),"passwordHash",c.passwordHash(),"correoSeguridad",c.correoSeguridad(),"requiereCambioPassword",c.requiereCambioPassword()));b.put("roles",roles);var out=e.executeJsonMutation(create,f.forWrite(i,m,c,b));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nUsuarioNuevoId"),"No se pudo crear la cuenta.");}
