 public PersistenceResult<Void> disable(DisableUser c, SessionIdentity i, RequestMetadata m) { var out=e.executeJsonMutation(status,f.forWrite(i,m,c,Map.of("usuario",map("usuarioId",c.usuarioId(),"accion","DESHABILITAR","motivo",c.motivo())))); return PaAdapterSupport.result(out,null,"No se pudo deshabilitar la cuenta."); }
 public PersistenceResult<Void> reactivate(ReactivateUser c, SessionIdentity i, RequestMetadata m) { var out=e.executeJsonMutation(status,f.forWrite(i,m,c,Map.of("usuario",map("usuarioId",c.usuarioId(),"accion","REACTIVAR","motivo",c.motivo())))); return PaAdapterSupport.result(out,null,"No se pudo reactivar la cuenta."); }
 public PersistenceResult<Void>assignRole(AssignRole c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(assign,f.forWrite(i,m,c,Map.of("asignacion",map("usuarioId",c.usuarioId(),"rolId",c.rolId()))));return PaAdapterSupport.result(out,null,"No se pudo asignar el rol.");}
 public PersistenceResult<Void>removeRole(RemoveRole c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(remove,f.forWrite(i,m,c,Map.of("asignacion",map("usuarioId",c.usuarioId(),"rolId",c.rolId(),"motivo",c.motivo()))));return PaAdapterSupport.result(out,null,"No se pudo retirar el rol.");}
 private UserAdminModels.Summary summary(Map<String,Object>r){return new UserAdminModels.Summary(SqlValues.longValue(r,"usuarioId"),SqlValues.string(r,"nombreUsuario"),SqlValues.string(r,"estadoCuenta"),SqlValues.instant(r,"fechaCreacion"),SqlValues.instant(r,"ultimoAccesoCorrecto"),SqlValues.intValue(r,"intentosFallidos"),SqlValues.instant(r,"bloqueadoHasta"),SqlValues.bool(r,"segundoFactorHabilitado"),SqlValues.longValue(r,"empleadoId"),SqlValues.string(r,"codigoEmpleado"),SqlValues.string(r,"empresa"),SqlValues.string(r,"numeroDocumento"),SqlValues.string(r,"empleado"),z(SqlValues.longValue(r,"rolesActivos")),z(SqlValues.longValue(r,"sesionesActivas")));}
 private static long z(Long x){return x==null?0:x;}private static Map<String,Object>map(Object...p){Map<String,Object>m=new LinkedHashMap<>();for(int x=0;x<p.length;x+=2)if(p[x+1]!=null)m.put((String)p[x],p[x+1]);return m;}
